    let lim = |base: i32| if peso_do_lado() > 0 { base + 3 } else { base };
    let disposicao = |i: isize| *(((m as isize) + 0x476a + 4 * i) as *const f32) as f64;
    let e = |o: usize| byte(ficha, o) as i32;
