            let fim = e;
            let r = cqc4_op(0x54c770, pj, 0x14);
            let r = if cqc4_depois(fim.as_ptr() as usize, r) { cqc4_op(0x54c770, pj, 4) } else { cqc4_op(0x54c5b0, pj, 3) };
