    cqc5_pb(p + 0x4e, cqc5_b(p + 0x4e) & 0xf4);
    cqc5_pd(p + 0x20, c1);
    cqc5_pd(p + 0xc, i2);
    cqc5_pd(p + 0x10, i1);
    cqc5_pd(p + 0x1c, c2);
